def _guess_caller_tag(kwargs: Dict[str, object]) -> str:
    """从 messages 的所有 system 段拼合后猜哪个 agent 在调用,用于 token 日志可读。"""
    messages = kwargs.get("messages") or []
    sys_text = ""
    for msg in messages:
        if not isinstance(msg, dict) or msg.get("role") != "system":
            continue
        c = msg.get("content")
        if isinstance(c, str):
            sys_text += c
        elif isinstance(c, list):
            for item in c:
                if isinstance(item, dict):
                    sys_text += str(item.get("text", ""))
    # minister 必须先判：大臣 system 末尾注入上月邸报全文(simulator 产出，含『日讲官』
    # 『档房书办』等词)，若先判 extractor/simulator 会把大臣对话误标成结算 agent。
    # 大臣自身开场白『扮演被皇帝召见』只在大臣 prompt 出现，且在邸报之前 → 用它先认。
    if "扮演被皇帝召见" in sys_text or "大臣扮演" in sys_text:
        return "minister"
    # 结算/写诏 agent 的 system = game_world_prompt(很长) + 自身 prompt，关键锚点在中后段，
    # 不能只看开头窗口。这几个 agent 不注入邸报，故全文搜各自唯一开场白即可。
    if "档房书办" in sys_text:
        return "extractor"
    if "日讲官兼推演官" in sys_text or "月末推演" in sys_text:
        return "simulator"
    if "诏书润色" in sys_text or "正式诏书" in sys_text:
        return "decree-writer"
    return "?"

def _apply_authority_change_item(
    db: GameDB, state: GameState, item: Dict[str, object],
) -> Dict[str, object]:
    """Apply one production-slot authority grant/revoke under the #611 contract."""
    if "dossier_id" not in item or item.get("dossier_id") in (None, ""):
        raise ValueError("missing_dossier_source")
    try:
        dossier_id = _parse_sqlite_id(item.get("dossier_id"))
    except (TypeError, ValueError):
        raise ValueError("missing_dossier_source") from None
    if dossier_id <= 0 or db.get_decree_dossier(dossier_id) is None:
        raise ValueError("missing_dossier_source")
    if not db.dossier_authorizes_effects(dossier_id):
        raise ValueError("dossier_not_effect_eligible")
    op = str(item.get("动作") or item.get("op") or "").strip()
    if op not in _AUTHORITY_GRANT_OPS | _AUTHORITY_REVOKE_OPS:
        raise ValueError("授权变更动作只收授予/收回")

    if op in _AUTHORITY_GRANT_OPS:
        holder_id = str(item.get("holder_id") or "").strip()
        privilege = str(item.get("privilege") or item.get("权项") or "").strip()
        scope = str(item.get("scope") or item.get("事域") or "").strip()
        if not holder_id or not privilege or not scope:
            raise ValueError("授予项必须含 holder_id/privilege/scope")
        if privilege not in AUTHORITY_PRIVILEGE_SET:
            raise ValueError("授权权项不在首批枚举")
        kind, separator, target_id = scope.partition(":")
        if not separator or not kind or not target_id:
            raise ValueError("invalid_authority_scope")
        if not db.conn.execute(
            "SELECT 1 FROM characters WHERE name=?", (holder_id,)
        ).fetchone():
            raise ValueError("授权对象不在人物档")
        origin = db.find_authority_by_origin(
            dossier_id, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if origin is not None:
            # Origin idempotency is independent of current applicability: a
            # revoked or expired grant remains the same durable authority row.
            return {
                "动作": "授予",
                "authority_id": int(origin["id"]),
                "dossier_id": dossier_id,
                "holder_id": holder_id,
                "privilege": privilege,
                "scope": scope,
                "reason": "same_dossier_replay",
            }
        effective_raw = item.get("effective_turn", item.get("生效回合"))
        expires_raw = item.get("expires_turn", item.get("失效回合"))
        effective_turn = (
            int(state.turn) if effective_raw in (None, "")
            else _parse_sqlite_id(effective_raw)
        )
        expires_turn = (
            None if expires_raw in (None, "")
            else _parse_sqlite_id(expires_raw)
        )
        if expires_turn is not None and expires_turn < effective_turn:
            raise ValueError("授权失效回合不得早于生效回合")
        existing = db.find_active_authority(
            state.turn, holder_id=holder_id, privilege=privilege, scope=scope,
        )
        if existing is not None:
            raise ValueError("duplicate_active_authority")
        cursor = db.conn.execute(
            "INSERT INTO authority_records "
            "(holder_id,privilege,scope,effective_turn,expires_turn,dossier_id) "
            "VALUES (?,?,?,?,?,?)",
            (
                holder_id, privilege, scope, effective_turn, expires_turn,
                dossier_id,
            ),
        )
        authority_id = int(cursor.lastrowid)
        return {
            "动作": "授予",
            "authority_id": authority_id,
            "dossier_id": dossier_id,
            "holder_id": holder_id,

def _attach_commission_staging_fields(
    payload: Dict[str, Any], item: Mapping[str, object], *, turn: int,
) -> None:
    """透传既有 staging 字段：assignee / participant_roster / due_turn。

    字段可在交办顶层，或挂在 grant 对象内（与 stage_grant_allocation_candidate
    kwargs 同口径）。期限单源＝due_turn；deadline_months / end_turn 仅作换算输入。
    """
    grant = item.get("grant") if isinstance(item.get("grant"), Mapping) else {}
    lead = str(
        item.get("assignee")
        or item.get("assignee_id")
        or item.get("assignee_name")
        or (grant.get("assignee") if grant else "")
        or (grant.get("assignee_id") if grant else "")
        or ""
    ).strip()
    if lead:
        payload["assignee"] = lead
    roster = item.get("participant_roster")
    if not isinstance(roster, list) and grant:
        roster = grant.get("participant_roster")
    if isinstance(roster, list) and roster:
        payload["participant_roster"] = list(roster)
    elif lead and not isinstance(payload.get("participant_roster"), list):
        payload["participant_roster"] = [{
            "character_id": lead, "tier": "主办", "role": "", "delegator_id": None,
        }]
    due_src = item if item.get("due_turn") not in (None, "", 0) else grant
    end_src = item if item.get("end_turn") not in (None, "", 0) else grant
    months_src = (
        item if item.get("deadline_months") not in (None, "", 0) else grant
    )
    # 与 stage_assignment / stage_grant 同缝：相对月数或绝对回合 → 绝对 due_turn。
    absolute_due = _assignment_absolute_end_turn(
        int(turn),
        end_turn=(due_src or item).get("due_turn") or (end_src or item).get("end_turn") or 0,
        deadline_months=(months_src or item).get("deadline_months") or 0,
    )
    if absolute_due > int(turn):
        payload["due_turn"] = absolute_due

def assess_foundation_tier(db: Any, commitment_ref: int) -> str:
    """根基三档：禁完成度数值列；读已过段数（实结算）/ 已投入 / 实际进度定性 band。"""
    row = _issue_row(db, int(commitment_ref))
    if row is None:
        return FOUNDATION_JUST_STARTED
    stages = normalize_commitment_stages(
        row["stages_json"] if "stages_json" in row.keys() else None
    )
    n_stages = len(stages)
    bar = int(row["bar_value"] or 0)
    stages_passed = _stages_passed_from_records(db, int(commitment_ref), n_stages)
    spent_amount, _fiscal_count = _spent_amount_and_fiscal_count(db, row)

    band = ""
    did = parse_dossier_id(row["origin_ref"] if "origin_ref" in row.keys() else "")
    if did is not None:
        progress = db.list_dossier_progress(int(did))
        if progress:
            band = str(progress[-1].get("progress_band") or "")

    rooted_bands = {"告成", "已成", "生根", "完工", "就绪"}
    mid_bands = {"在办", "过半", "在途", "推进"}

    if band in rooted_bands or bar >= _BAR_ROOTED:
        return FOUNDATION_ROOTED
    if n_stages >= 2 and stages_passed >= n_stages:
        return FOUNDATION_ROOTED
    if (
        band in mid_bands
        or (_BAR_MID_LOW <= bar < _BAR_ROOTED)
        or (n_stages >= 2 and 0 < stages_passed < n_stages)
        or (spent_amount >= _SPENT_AMOUNT_HALFWAY and bar >= _BAR_MID_LOW)
    ):
        return FOUNDATION_HALFWAY
    return FOUNDATION_JUST_STARTED

def _stage_office(shared_text: str) -> Dict[str, Any]:
    from ming_sim.action_materialize import (
        _apply_existing_appointment_hit, _same_direction_office_hits,
    )
    from types import SimpleNamespace
    hits = _same_direction_office_hits(
        db, int(state.turn), name=str(appointment_fields["name"]),
        office=str(appointment_fields["office"]),
        action=str(appointment_fields["appoint_action"]),
        region_id=str(appointment_fields.get("region_id") or ""),
    )
    if len(hits) > 1:
        _reject(rejected, item, "同向任免候选不唯一", "invalid_state", source)
        return None
    if hits:
        oid = _apply_existing_appointment_hit(
            SimpleNamespace(db=db), hits[0],
            extracted_mode=appointment_fields.get("mode"),
            region_id=str(appointment_fields.get("region_id") or ""),
            minister_name=minister_name, turn=int(state.turn),
            annotate=True,
            recommendation_fields={
                key: payload[key]
                for key in ("reason", "recommendation", "faction")
                if payload.get("recommendation") and key in payload
            },
        )
        return {"id": oid, "kind": "office"}
    if appointment_fields["appoint_action"] == "任命":
        from ming_sim.session import _appointment_intent_is_current_office_noop
        if _appointment_intent_is_current_office_noop(
            db, appointment_fields["name"], appointment_fields["office"],
            content=getattr(db, "content", None),
        ):
            return None
    # office 成案链只吃任免字段；禁把 grant 的 execution_surface 等带进
    # appointment 案卷（会撞「execution_surface 与案卷动作策略不符」）。
    office_payload = dict(appointment_fields or {})
    office_payload["text"] = shared_text
    if "affair_declaration" in payload:
        office_payload["affair_declaration"] = payload["affair_declaration"]
    for key in ("reason", "recommendation", "faction", "replaces"):
        if key in payload:
            office_payload[key] = payload[key]
    oid = db.stage_pending_action(
        int(state.turn),
        "office",
        str(office_payload["appoint_action"]),
        minister_name,
        office_payload,
        source_chat_turn_id=source_chat_turn_id,
    )
    return {"id": oid, "payload": office_payload, "kind": "office"}

def _normalize_grant_transport(value: Mapping[str, Any]) -> Dict[str, Any]:
    transport = dict(value)
    # Draft transport historically used 目标ID and Chinese mode labels;
    # canonical FieldSpec validation happens only after those aliases normalize.
    if "target_id" not in transport and "目标" not in transport and "目标ID" in transport:
        transport["target_id"] = transport["目标ID"]
    raw_mode = transport.get("mode", transport.get("颁布方式"))
    if raw_mode not in (None, ""):
        transport["mode"] = _directive_mode(raw_mode) or raw_mode
    normalized = assert_action_candidate_shape({**transport, "kind": "grant_allocation"})
    projected = project_cluster_fields("grant_allocation", normalized)
    if projected.get("grant_action") != "协饷" and not projected.get("target_kind"):
        projected["target_kind"] = "policy"
    return projected

def _apply_on_restore(
    self,
    state: GameState,
    region_id: str,
    event: Event,
    edict_id: int | None,
    actor: str,
    reason: str,
    origin_ref: str = "",
) -> List[Dict[str, object]]:
    """收复瞬间用 region.on_restore 覆盖主字段，记 region_logs。"""
    region_def = self.content.regions.get(region_id)
    if region_def is None or not region_def.on_restore:
        return []
    preset = region_def.on_restore
    row = self.conn.execute("SELECT * FROM regions WHERE id = ?", (region_id,)).fetchone()
    if row is None:
        return []
    all_direct = REGION_SCORE_FIELDS + REGION_QUANTITY_FIELDS + REGION_TEXT_FIELDS
    out: List[Dict[str, object]] = []
    for raw_field, value in preset.items():
        if raw_field == "fiscal":
            if not isinstance(value, dict):
                continue
            fiscal = json.loads(str(row["fiscal"] or "{}"))
            for sub_field, sub_val in value.items():
                if sub_field not in FISCAL_SCORE_FIELDS:
                    continue
                old_sub = fiscal.get(sub_field, 0)
                new_sub = int(sub_val)
                if int(old_sub) == new_sub:
                    continue
                fiscal[sub_field] = new_sub
                self.conn.execute(
                    "INSERT INTO region_logs (turn, year, period, region_id, field, old_value, new_value, delta, reason, event_id, edict_id, actor, origin_ref) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (state.turn, state.year, state.period, region_id,
                     sub_field, str(old_sub), str(new_sub), new_sub - int(old_sub),
                     f"收复重置：{reason}", event.id, edict_id, actor, origin_ref),
                )
                out.append({
                    "region": row["name"], "field": sub_field,
                    "label": REGION_FIELD_LABELS.get(sub_field, sub_field),
                    "old": old_sub, "new": new_sub,
                    "delta": new_sub - int(old_sub), "reason": f"收复重置：{reason}",
                })
            self.conn.execute(
                "UPDATE regions SET fiscal = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (json.dumps(fiscal, ensure_ascii=False), region_id),
            )
            continue
        if raw_field == "controlled_by":
            continue  # 控制权已写完，跳过
        if raw_field not in all_direct:
            continue
        old_val = row[raw_field]
        if raw_field in (REGION_SCORE_FIELDS + REGION_QUANTITY_FIELDS):
            # #648（ADR 0088）：on_restore 是 content 静态真源→存档接缝，population
            # 已全线「人」，落本档前按存档口径换算（新档原样；无标旧档无损÷10⁴）。
            new_val: object = (
                self.scale_content_population_to_save_unit(value)
                if raw_field == "population" else int(value)
            )
        else:
            new_val = str(value)
        if str(old_val) == str(new_val):
            continue
        self.conn.execute(
            f"UPDATE regions SET {raw_field} = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
            (new_val, region_id),
        )
