def buildings_report(self, region_id: str = "", qualitative: bool = False) -> str:
    """月末奏报 / web 用建筑盘面摘要。region_id 为空取全国。"""
    if region_id:
        rows = self.conn.execute(
            "SELECT * FROM buildings WHERE region_id = ? ORDER BY category, name", (region_id,)
        ).fetchall()
    else:
        rows = self.conn.execute(
            "SELECT * FROM buildings ORDER BY region_id, category, name"
        ).fetchall()
    if not rows:
        return "（暂无建筑在册）"
    lines: List[str] = []
    for r in rows:
        metric = str(r["output_metric"])
        if metric in ("民心", "皇威") and qualitative:
            out = building_output_effect(metric, r["output_amount"])
        elif metric:
            out = f"产出{metric}{r['output_amount']}"
        else:
            out = "无结算产出"
        if qualitative:
            level, condition, risk = building_qualitative_fields(r)
            lines.append(
                f"{r['name']}（{r['category']}·{r['region_id']}）规模{level}，"
                f"{condition}，维护{r['maintenance']}{MONEY_UNIT}/{TURN_UNIT}，风险{risk}，{out}。{r['status']}"
            )
            continue
        lines.append(
            f"{r['name']}（{r['category']}·{r['region_id']}）等级{r['level']}，"
            f"完好{r['condition']}，维护{r['maintenance']}{MONEY_UNIT}/{TURN_UNIT}，"
            f"风险{r['risk']}，{out}。{r['status']}"
        )
    return "\n".join(lines)

def _normalize_event_outcome_label(event_id: str, label: str, content: GameContent) -> str:
    allowed = _closed_outcome_labels(content, event_id)
    compact = re.sub(r"\s+", "", str(label or ""))
    if not compact:
        return ""
    for canonical in allowed:
        if compact == re.sub(r"\s+", "", canonical):
            return canonical
    alias = _STRATEGIC_EVENT_OUTCOME_LABEL_ALIASES.get(event_id, {}).get(compact, "")
    return alias if alias in allowed else ""

def _minister_game_world_prompt(prompt: str) -> str:
    """给场景的世界观说明只保留呈现口径，不把引擎量表喂给角色。"""
    lines = []
    for line in prompt.splitlines():
        if "国势核心数值四个：" in line:
            line = "- 国势以奏报呈现：国库、内库保留钱粮口径；民心、皇威只作定性描述。"
        elif "地区盘面使用两京十三省的核心字段：" in line:
            line = "- 地区盘面中人口、粮食、田亩、隐田、每回合税收等可数物照实呈报；民心、动乱、士绅阻力、军事压力以定性描述呈报。"
        elif "军队盘面使用主要军队核心字段：" in line:
            line = "- 军队盘面中驻地、统帅、兵种、人数、月饷与欠饷等可数物照实呈报；补给、士气、训练、装备、火器、机动、忠诚以定性描述呈报；随军大炮照门数呈报。"
