            cutoff_seq = int(crow["night_seq"] or 0)

    def _before_cutoff(seq: int, turn_id: int) -> bool:
        if cutoff_id <= 0 or cutoff_seq is None:
            return True
        if int(seq) < int(cutoff_seq):
