        src = int(entry.get("source_chat_turn_id") or 0)
        origin = int(entry.get("origin_chat_turn_id") or 0)
        if cutoff_id > 0 and cutoff_seq is not None:
            # 本轮/后续轮声明账不入；框架账（双 0）按 seq 截止到本轮之前。
            if src == cutoff_id or origin == cutoff_id:
                continue
