                continue
            if src <= 0 and origin > 0 and origin not in prior_turn_ids:
                continue
            if src <= 0 and origin <= 0:
                entry_seq = entry.get("order_key")
                if entry_seq is None:
                    entry_seq = entry.get("seq") or 0
                if float(entry_seq) >= float(cutoff_seq):
                    continue
