        return None, RejectedItem(
            item={"raw_value": appointment}, reason="任免载荷须为对象",
            category="invalid_shape", source=source,
        )
    action = str(
        appointment.get("appoint_action") or appointment.get("action") or "任命"
    ).strip() or "任命"
    if action not in {"任命", "罢免"}:
        return None, RejectedItem(
            item=dict(appointment), reason=f"任免动作非法：{action}",
            category="invalid_enum", source=source,
        )
    name = str(appointment.get("name") or "").strip()
    office = str(appointment.get("office") or appointment.get("new_office") or "").strip()
    if not name:
        return None, RejectedItem(
            item=dict(appointment), reason="任免声明缺 name",
            category="invalid_shape", source=source,
        )
    if action == "任命" and not office:
        return None, RejectedItem(
            item=dict(appointment), reason="任命声明缺 office",
            category="invalid_shape", source=source,
        )
    payload: Dict[str, Any] = {"name": name, "office": office, "appoint_action": action}
    mode = appointment.get("mode")
    if mode is not None:
        if not isinstance(mode, str) or mode not in {"ordinary", "midzhi"}:
            return None, RejectedItem(
                item=dict(appointment), reason=f"任免模式非法：{mode}",
                category="invalid_enum", source=source,
            )
        payload["mode"] = mode
    tenure = str(
        appointment.get("appointment_tenure") or appointment.get("任别") or ""
    ).strip()
    if tenure:
        payload["appointment_tenure"] = tenure
    # Typed 任所原样透传；不从官名推断（地方/督抚/边镇任命必填；中央可空）。
    seat = str(
        appointment.get("region_id") or appointment.get("任所") or ""
    ).strip()
    if seat:
        payload["region_id"] = seat
    return payload, None

def _payload_dict(candidate: Dict[str, Any]) -> Dict[str, Any]:
    payload = candidate.get("payload")
    if isinstance(payload, dict):
        return payload
    raw = candidate.get("payload_json")
    if raw in (None, ""):
        return {}
    loaded = json.loads(str(raw))
    return loaded if isinstance(loaded, dict) else {}

def _arrears_order_displacement_entries(
    db: Any, config: Dict[str, int], region_id: str, st: Dict[str, Any], turn: int,
) -> List[Dict[str, Any]]:
    """以当月 Repaid/省池旧欠流量反演实偿，再按同一总实偿重放祖制旧欠序，投影让位。

    F1.6-③ / F2.2：只报因 arrears_priority 让位新增受损与胜出旨 origin_ref。
    不扩 schema、不新表；复用 region_logs Repaid 与 army_logs 省池旧欠流量。
    """
    from ming_sim.pay_order import (
        ARREARS_SUBJECTS, DEFAULT_ARREARS_PRIORITY, resolve_pay_order_overrides,
    )

    resolved = resolve_pay_order_overrides(config, region_id, turn)
    default_order = tuple(sorted(ARREARS_SUBJECTS, key=DEFAULT_ARREARS_PRIORITY.__getitem__))
    if resolved is None or resolved.arrears_order == default_order:
        return []

    actual_repaid = {s: 0.0 for s in ARREARS_SUBJECTS}
    rows = db.conn.execute(
        "SELECT field, delta FROM region_logs WHERE turn=? AND region_id=? "
        "AND field IN ('settle_官俸欠_Repaid','settle_宗禄欠_Repaid')",
        (turn, region_id),
    ).fetchall()
    for row in rows:
        subject = "官俸欠" if "官俸欠" in str(row["field"]) else "宗禄欠"
        # Repaid 留痕 delta 为负；取绝对值作实偿流量
        actual_repaid[subject] += max(0.0, -float(row["delta"] or 0))
    army = db.conn.execute(
        "SELECT COALESCE(SUM(CASE WHEN CAST(old_value AS REAL)>CAST(new_value AS REAL) "
        "THEN CAST(old_value AS REAL)-CAST(new_value AS REAL) ELSE 0 END),0) AS v "
        "FROM army_logs WHERE turn=? AND field='province_pay_arrears' AND army_id IN "
        "(SELECT id FROM armies WHERE pay_source_region=?)", (turn, region_id),
    ).fetchone()
    actual_repaid["军饷欠"] = float(army["v"] or 0)

    # 偿前 CLAIM = 月末存量 + 当月实偿（action 补饷已在 settle 前扣，不入本瀑布）
    claims = {
        s: max(0.0, float(st.get(s, 0) or 0) + actual_repaid[s])
        for s in ARREARS_SUBJECTS
    }
    pool = sum(actual_repaid.values())
    if pool <= 1e-9:
        return []
    default_repaid = _waterfall_allocate(default_order, claims, pool)

    arrears_class = {"军饷欠": "军户", "官俸欠": "官僚", "宗禄欠": "宗藩"}
    out: List[Dict[str, Any]] = []
    for subject in default_order:
        displaced = default_repaid[subject] - actual_repaid[subject]
        if displaced <= 1e-9:
            continue
        origin = _priority_override_origin_for(
            db, config, region_id, turn, subject, displaced, claims, pool,
            subjects=ARREARS_SUBJECTS,
            default_priority=DEFAULT_ARREARS_PRIORITY,
            key_prefix="arrears_priority",
            order_of=lambda resolved: resolved.arrears_order,
        )
        if origin:
            out.append({
                "subject_kind": "region", "subject_id": region_id, "region": region_id,
                "metric": "欠禄额", "window_turns": 1, "value": displaced,
                "origin_ref": origin, "affected_class": arrears_class[subject],
                "detail": f"旧欠序让位_{subject}",
            })
    return out

def _content_population_effect_for_save(
    db: GameDB, effect: Dict[str, object]
) -> Dict[str, object]:
    """#648（ADR 0088/F4）：content 静态人口量已全线「人」，落本档前按存档口径换算。

    新档（人）原样；无标旧档（万人）region_delta.population ÷10⁴（迁移后 content
    人口值均为 10⁴ 整倍数，整除无损）。只换算 region_delta.*.population，其余段浅拷贝透传。
    只用于 content 事件真源（effect_on_trigger / event_to_issue 持久化）；LLM 产 delta
    已按本档口径写，不得经此换算。"""
    region_delta = effect.get("region_delta")
    if not isinstance(region_delta, dict) or not region_delta:
        return effect
    if db.population_unit == POPULATION_UNIT_PERSONS:
        return effect
    scaled: Dict[str, object] = {**effect}
    scaled_region_delta: Dict[str, object] = {}
    for rid, fields in region_delta.items():
        if isinstance(fields, dict) and "population" in fields:
            scaled_fields = {**fields}
            try:
                scaled_fields["population"] = db.scale_content_population_to_save_unit(
                    fields["population"]
                )
            except (TypeError, ValueError):
                pass  # 非整人口值交由下游 apply_region_deltas 既有拒收留痕，不在此静默改写
            scaled_region_delta[rid] = scaled_fields
        else:
            scaled_region_delta[rid] = fields
    scaled["region_delta"] = scaled_region_delta
    return scaled

def _legacy_commitment_stop_gate(resolve_condition: object) -> Dict[str, str]:
    text = str(resolve_condition or "").strip()
    match = re.fullmatch(r"(character\.[^.]+\.loyalty)\s*((?:>=|>)\s*\d+)", text)
    if not match:
        return {}
    return {match.group(1): match.group(2).replace(" ", "")}

def displaced_talent_pool_results(displaced_parts: object) -> List[Dict[str, object]]:
