def _strip_controlled_namespace(text: str, namespace: str) -> str:
    """Strip only the extractor's exact namespace wrappers, never prose."""
    if text.startswith("@"):
        return text[1:]
    prefix = f"{namespace}."
    if text.startswith(prefix):
        return text[len(prefix):]
    return text

def _entity_delta_has_work(
    raw: object,
    *,
    aliases: Dict[str, str],
    numeric_fields: tuple[str, ...],
    text_fields: tuple[str, ...] = (),
) -> bool:
    if not isinstance(raw, dict):
        return False
    numeric = set(numeric_fields)
    text = set(text_fields)
    for changes in raw.values():
        if not isinstance(changes, dict):
            continue
        for raw_field, value in changes.items():
            field = aliases.get(str(raw_field).strip(), str(raw_field).strip())
            if field in numeric and _nonzero_int(value):
                return True
            if field in text and _nonempty_text(value):
                return True
    return False

def relation_dimension(source: str, target: str) -> str:
    """维度标记：任一端为皇帝节点即君臣边，否则大臣边。"""
    return DIMENSION_JUNXIN if EMPEROR_NODE in (source, target) else DIMENSION_DACHEN

def stages_to_json(stages: object) -> str:
    """Serialize stages for durable DB write.

    Designed string surface: JSON array string is parsed, not char-iterated.
    Invalid non-empty strings raise ValueError (never silently store ``[]``).
    ``None`` / empty / ``[]`` → ``"[]"``.
    """
    if stages is None:
        return "[]"
    if isinstance(stages, str):
        text = stages.strip()
        if not text or text in ("[]", "{}"):
            return "[]"
        try:
            data = json.loads(text)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"stages_json 须为 JSON 数组字符串，解析失败：{text[:80]!r}"
            ) from exc
        if not isinstance(data, (list, tuple)):
            raise ValueError(
                f"stages_json 须为 JSON 数组，得 {type(data).__name__}"
            )
        if len(data) == 0:
            return "[]"
        normalized = normalize_commitment_stages(data)
        if not normalized:
            raise ValueError(
                "stages_json 无有效段（每段须 due_turn>0 与 criterion_text）"
            )
        return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
    if isinstance(stages, (list, tuple)):
        if not stages:
            return "[]"
        normalized = normalize_commitment_stages(list(stages))
        # 非空 list 归一后无有效段：与 str 支同响亮拒绝，禁静默存 []
        if not normalized:
            raise ValueError(
                "stages_json 无有效段（每段须 due_turn>0 与 criterion_text）"
            )
        return json.dumps(normalized, ensure_ascii=False, separators=(",", ":"))
    raise ValueError(f"stages_json 类型非法：{type(stages).__name__}")

def _expected_satisfaction(
    affected_parties: Sequence[Dict[str, Any]],
) -> Dict[Tuple[str, str], int]:
    """Map typed signed reactions → delta; zero-reaction parties are omitted upstream."""
    expected: Dict[Tuple[str, str], int] = {}
    for party in affected_parties or []:
        if not isinstance(party, dict):
            continue
        kind = str(party.get("kind") or "")
        key = str(party.get("key") or "")
        magnitude = _REACTION_INTENSITY.get(str(party.get("intensity") or ""))
        sign = _REACTION_SIGN.get(str(party.get("direction") or ""))
        if kind not in {"faction", "class"} or not key or magnitude is None or sign is None:
            continue
        delta = sign * magnitude
        if delta == 0:
            # 零反应不入清单
            continue
        expected[(kind, key)] = delta
    return expected

def _judge_payload_from_prompt(prompt: object) -> dict:
    """Decode the user JSON exactly as serialized into the real CLI prompt."""
    if not isinstance(prompt, str):
        raise RuntimeError("CLI judge trace has no prompt")
    marker = "【皇帝/输入】\n"
    positions = [index for index in range(len(prompt)) if prompt.startswith(marker, index)]
    if len(positions) != 1:
        raise RuntimeError(f"CLI judge prompt must have one user payload; got {len(positions)}")
    start = positions[0] + len(marker)
    try:
        payload, consumed = json.JSONDecoder().raw_decode(prompt[start:])
    except json.JSONDecodeError as exc:
        raise RuntimeError("CLI judge prompt user payload is not complete JSON") from exc
    remainder = prompt[start + consumed:]
    if not remainder.startswith("\n\n【") or not isinstance(payload, dict):
        raise RuntimeError("CLI judge prompt user payload boundary is invalid")
    return payload

  const itemsPart = totalMatch ? cleaned.slice(0, totalMatch.index).replace(/。$/, "") : cleaned.replace(/。$/, "");
  return {
    items: itemsPart.split("；").map((item) => item.replace(/^。+|。+$/g, "").trim()).filter(Boolean),
    tail: totalMatch?.[1] || "",
  };
};


// 玩家面板会收到英文 id（region_id/army_id/power_id）或编号；统一映射为中文名。

def _runtime_float(value: object, default: float) -> float:
    try:
        return float(value) if value not in (None, "") else default
    except (TypeError, ValueError):
        return default

def chat_stream(self, minister_name: str, message: str) -> Iterator[Dict[str, Any]]:
    # #1849 reopen：召对只剩殿上一个入口；按大臣/密令/场外路由整条删除。
    from ming_sim.audience_night import SCENE_CHAT_SPEAKER
    if minister_name != SCENE_CHAT_SPEAKER:
        yield {"type": "error", "message": "召对只从殿上入口进行。"}
        return
    # #1847 N6：判空可读 strip；召对玩家原文运输不得赋 strip 结果。
    text = str(message or "")
    if not text.strip():
        yield {"type": "error", "message": "问话不能为空。"}
        return
    # #498：结算/亲裁相位不得召对（夜不跨月）。锁前查仅快速失败；权威判定在持 gate 后复查
    # （见下），防 TOCTOU——SUMMONING 通过后等 gate 时被结算改相位仍会开夜。
    if getattr(self.state, "turn_phase", None) in FRONT_HALF_DONE_PHASES:
        yield {"type": "error", "message": "月末结算/亲裁进行中，暂不能召对。"}
        return
    # 整轮（含转译与高亮尾随）共用一次队列票据——关闭/fixture 必须等其完成。
    pending_ticket = self._mark_pending_write()
    if pending_ticket is None:
        yield {"type": "error", "message": "当前会话正在关闭，请回菜单重新进入。"}
        return
    # #1353 r10：屏障已受理则拒后序流式聊天（与 seal 合流）；否则 prologue/epilogue
    # 经 ticketed gate（写段序）。LLM 仍在无锁窗（AC10）。
    if self._runtime_write_queue().has_open_barrier():
        self._complete_pending_write(pending_ticket)
        yield {
            "type": "error",
            "message": "本夜收夜中，暂不能召对。",
            "code": "night_closing",
        }
        return
    write_gate = self._ticketed_write_gate(pending_ticket)
    bare_write_gate = self._runtime_write_gate()
    chat_turn_id = 0
    before_snapshot: Dict[str, Any] = {}
    accepted_turn = 0
    # #498 AC10：prologue 持锁写库后立刻释放，LLM 不持 write_gate——
    # 颁诏入口可并发观测 generating 并有界超时 fail-closed，不被挂起回话永久挡死。
    # #542 r6g：Lock.locked() 不记 owner——本路径自记是否仍持 gate，只放自己的锁。
    gate_held = True
    try:
        write_gate.acquire()
    except TicketCancelled:
        self._complete_pending_write(pending_ticket)
        yield {"type": "error", "message": "当前会话正在关闭，请回菜单重新进入。"}
        return
    try:
        # 权威相位复查（持 gate 内，建 chat turn/开夜/写库之前）：等锁期间若被结算改相位则拒。
        if getattr(self.state, "turn_phase", None) in FRONT_HALF_DONE_PHASES:
            self._complete_pending_write(pending_ticket)
            yield {"type": "error", "message": "月末结算/亲裁进行中，暂不能召对。"}
            return
        # #612：CLOSING 冻结新对话——唯一玩家输入准入真源，无平行 status 判断。
        if hasattr(self.db, "conn"):
            from ming_sim.audience_night import (
                AudienceNightError,
                assert_night_accepts_player_input,
            )
            try:
                assert_night_accepts_player_input(self.db, what="召对")
            except AudienceNightError as err:
                if getattr(err, "code", "") == "night_closing":
                    self._complete_pending_write(pending_ticket)
                    yield {
                        "type": "error",
                        "message": str(err) or "本夜收夜中，暂不能召对。",
                        "code": "night_closing",
                    }
                    return
                raise
        if self._audience_turn_in_flight(minister_name):
            self._complete_pending_write(pending_ticket)
            yield {"type": "error", "message": "本夜上一轮回奏仍在进行，请稍候再问。"}
            return
        accepted_turn = int(self.state.turn)
        chat_turn_id, before_snapshot = self._start_chat_turn(
            minister_name,
            message=text,
            attach_to_hall=True,
        )

def string_list(value: object, path: str) -> List[str]:
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise SystemExit(f"设定字段应为字符串数组：{path}")
    return [str(item) for item in value]

def _validate_summon_method(method: str, *, default: str) -> str:
    """校验召法白名单（summon_enter / record_summon_in_transit 共用单一真源）。"""
    m = str(method or default).strip()
    if m not in SUMMON_METHODS:
        raise AudienceNightError(
            f"召法非法：{m!r}（须为 {'/'.join(sorted(SUMMON_METHODS))}）",
            code="bad_summon_method",
        )
    return m

def play_turn(session: GameSession) -> None:
    """一回合 CLI 驱动：召见 → 审阅 → 颁诏推演。"""
    snap = session.begin_turn()
    _print_header(session)
    if session.previous_summary:
        print(session.previous_summary)
        print()
    if snap.deaths_this_turn:
        names = "、".join(f"{d['name']}（{d['office']}）" for d in snap.deaths_this_turn)
        print(f"【讣闻】本{TURN_UNIT}卒：{names}\n")
    from ming_sim.issues import show_active_issues
    show_active_issues(session.db)

    pending_character: Optional[Character] = None
    while True:
        if session.current_phase() == TurnPhase.SUMMONING:
            character = pending_character or choose_minister(session)
            pending_character = None
            if character is None:
                action = review_directives(session)
            else:
                chat_action = minister_chat(session, character, selected=True)
                if chat_action == "dismiss":
                    continue
                if chat_action.startswith("summon:"):
                    pending_character = session.content.characters[chat_action.split(":", 1)[1]]
                    continue
                # court_break 或对话结束 → 审阅
                action = review_directives(session)
        else:
            action = review_directives(session)

        if action == "back":
            continue
        if action == "skip":
            turn_before = int(session.state.turn)
            failed_before = _failed_secret_order_ids(session, turn_before)
            try:
                # #1353 fold-in r8：颁诏/退朝前挂唯一 write_gate，使 resolve 收夜 drain 同流。
                _cli_write_gate(session)
                result = session.advance_without_decree()
                report = _submit_cli_decisions(session, result)
            except (ValueError, SettlementAbort, LLMUnavailable, LLMContractError) as error:
                # 跳过与颁诏共享可恢复结算语义：失败后留在本回合循环，允许重试。
                # #1353 fold-in r8：统一重试耗尽的 LLMUnavailable 不退出 CLI。
                # #1700：空 simulator 的 LLMContractError 同形，不落到 run_cli「程序中止」。
                print(f"\n{error}")
                _print_pending_action_failures(
                    _new_secret_order_failure_payloads(session, turn_before, failed_before)
                )
                continue
            _print_pending_action_failures(
                _new_secret_order_failure_payloads(session, turn_before, failed_before)
            )
            if result is not None:
                print(report)
                if getattr(session.state, "ended", False):
                    return
                if getattr(result, "advanced", False) or int(session.state.turn) > turn_before:
                    session.end_turn()
                    return
            else:
                return
            continue
        if action == "issue":
            turn_before = int(session.state.turn)
            failed_before = _failed_secret_order_ids(session, turn_before)
            try:
                # #1353 fold-in r8：颁诏/退朝前挂唯一 write_gate，使 resolve 收夜 drain 同流。
                _cli_write_gate(session)
                result = session.resolve_turn()
                report = _submit_cli_decisions(session, result)
            except (ValueError, SettlementAbort, LLMUnavailable, LLMContractError) as error:
                # 恢复态守门 / 结算中止 / 欠账耗尽（#1353 r8）/ 契约失败（#1700）：打印指引后留在
                # 本回合交互循环——玩家重按 issue/skip 即重试整段，CLI 不退出。
                print(f"\n{error}")
                _print_pending_action_failures(
                    _new_secret_order_failure_payloads(session, turn_before, failed_before)
                )
                continue

def _canon_person_id_keys(
    ids: Any, *, db: Any, content: Any,
) -> List[str]:
    """生 character_id 列表 → 熟键（非人滤 + canon），保序去重。

    除名闸 prior 侧与 validated 必须同走此接缝，禁平行第三套 id 语义。
    """
    out: List[str] = []
    for raw in ids or []:
        canon = _canon_person_id_key(raw, db=db, content=content)
        if canon and canon not in out:
            out.append(canon)
    return out

def _directive_mode(value: object) -> Optional[str]:
    """Normalize the extractor's typed mode value, never player prose."""
    return {
        "中旨直发": "midzhi",
        "midzhi": "midzhi",
        "普通": "ordinary",
        "ordinary": "ordinary",
    }.get(str(value or "").strip())

def _normalize_unknown_participant_names(
    names: Optional[List[str]] = None,
) -> List[str]:
    cleaned: List[str] = []
    for raw in names or []:
        name = str(raw or "").strip()
        if name and name not in cleaned:
            cleaned.append(name)
    return cleaned

def held_authority_context(
    character: Character, db: GameDB, *, turn: Optional[int] = None,
) -> str:
    """大臣可见的在持授权定性摘要；裸 authority_records.id 永不入面。"""
    if turn is None:
        turn = int(db.load_state().turn)
    rows = db.list_active_authorities(int(turn), holder_id=character.name)
    if not rows:
        return ""
    labels: List[str] = []
    seen: set[str] = set()
    for row in rows:
        priv = str(row.get("privilege") or "").strip()
        if not priv or priv in seen:
            continue
        seen.add(priv)
        labels.append(_PRIVILEGE_QUALITATIVE.get(priv, priv))
    if not labels:
        return ""
    return f"【在持授权】{'、'.join(labels)}。"

