def _merge_compliant_promulgation_items(
    accumulated: List[Dict[str, object]],
    fresh: Sequence[Dict[str, object]],
) -> List[Dict[str, object]]:
    """跨补交轮次并集保留已合规判决：先到先留，后轮不得冲掉前轮好判（#1753）。

    输入仅来自 _collect_compliant_promulgation_items 已过闸项，不再二次类型过滤。
    """
    by_id: Dict[int, Dict[str, object]] = {}
    order: List[int] = []
    for row in list(accumulated) + list(fresh):
        dossier_id = int(row["dossier_id"])
        if dossier_id in by_id:
            continue
        by_id[dossier_id] = row
        order.append(dossier_id)
    return [by_id[item] for item in order]

def project_target_locality_matrix_prompt() -> str:
    """由 TARGET_KIND_LOCALITY_SCOPES 投影可接受面（供共同 prompt 消费；禁手抄）。"""
    groups: Dict[frozenset[str], list[str]] = {}
    for kind, scopes in TARGET_KIND_LOCALITY_SCOPES.items():
        groups.setdefault(scopes, []).append(kind)
    parts: list[str] = []
    for scopes in sorted(groups, key=lambda s: (sorted(s), len(s))):
        kinds = "|".join(sorted(groups[scopes]))
        if len(scopes) == 1:
            only = next(iter(scopes))
            parts.append(f"{kinds}仅{only}")
        else:
            parts.append(f"{kinds}∈{'|'.join(sorted(scopes))}")
    return (
        "target_kind×locality_scope 可接受面（" + "；".join(parts) + "）"
    )

def _resolve_haircut_param(p: Dict[str, Any]) -> Dict[str, int]:
    """#653 折发系数参（p["due_haircut_bp"]）：{科目: 万分数}，域 (0,10000]，越界 fail-loud。
    缺省/空 dict=无折（逐字节默认路径）。"""
    raw = p.get("due_haircut_bp")
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise ValueError(f"param due_haircut_bp 非字典：{raw!r}")
    out: Dict[str, int] = {}
    for hk, bp in raw.items():
        if hk not in _DUE_KEYS:
            raise ValueError(f"due_haircut_bp 含未知科目 {hk}")
        if isinstance(bp, bool) or not isinstance(bp, int):
            raise ValueError(f"due_haircut_bp[{hk}] 非整数：{bp!r}")
        if not (0 < bp <= 10000):
            raise ValueError(f"due_haircut_bp[{hk}] 须在 (0,10000]：{bp}")
        if bp != 10000:
            out[hk] = bp
    return out

def _army_noop_error(army_id: str, row: sqlite3.Row, raw_field: object, value: object) -> str:
    field = ARMY_FIELD_ALIASES.get(str(raw_field).strip(), str(raw_field).strip())
    if field == "reason":
        return ""
    # #319：latched 静默 no-op 与写缝同口径——战略信封预检须拒整封，不得半落兄弟结果。
    # loyalty 不进此函数：caller 对 field=="loyalty" 先 continue，再走
    # fold_loyalty_alias_delta + latched_army_field_effect_permitted +
    # compute_loyalty_soft_adjust；勿在此再堆 loyalty 专属预测（死分支）。
    if bool(row["is_mutinied"]):
        if field == "manpower":
            if not latched_army_field_effect_permitted(field, value):
                return _noop_error("army", army_id, raw_field, value)
        else:
            return _noop_error("army", army_id, raw_field, value)
    if field == "cannon_equipment":
        old_value = int(row[field])
        if max(0, min(12, old_value + int(value))) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field == "arrears":
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_SCORE_FIELDS:
        old_value = int(row[field])
        delta = int(value)
        net_pct = int(((legacy_mods.get("armies") or {})
                       .get(army_id) or {}).get(field, 0) or 0)
        if net_pct:
            delta = db.apply_legacy_pct(delta, net_pct)
        if max(0, min(100, old_value + delta)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_QUANTITY_FIELDS:
        old_value = int(row[field])
        if max(0, old_value + int(value)) == old_value:
            return _noop_error("army", army_id, raw_field, value)
        return ""
    if field in ARMY_TEXT_FIELDS:
        return ""
    return ""

def _fiscal_levy_base_transport(
    meta: Dict[str, object],
    p: Dict[str, object],
    liao_seed: float,
    region_id: str,
) -> float:
    if _SETTLE_META_BASE_TRANSPORT_KEY in meta:
        return max(
            0.0,
            _as_float(
                meta[_SETTLE_META_BASE_TRANSPORT_KEY],
                ctx=f"{region_id}.settle._meta.{_SETTLE_META_BASE_TRANSPORT_KEY}",
            ),
        )
    seed_transport = _as_float(p.get("起运定额"), ctx=f"{region_id}.settle.p.起运定额")
    return max(0.0, seed_transport - liao_seed)

